begin;
-- Read-only credit from existing immutable approvals: no attendance, activity,
-- salary, assignment, policy or fixture records are generated by this migration.
create function portal_private.internal_learning_receipts(p_user uuid)
returns table(submission_id uuid,span tstzrange,current_receipt boolean,receipt jsonb)
language sql stable security definer set search_path='' as $$
 with sources as (
 select s.*,approved.id approval_id,approved.actor_id approved_by,approved.created_at approved_at,
 latest.id latest_decision_id,latest.action latest_action,
 portal_private.internal_training_current(s.attendance_id) source_current,
 not exists(select 1 from public.crm_internal_training_submissions n where n.attendance_id=s.attendance_id and n.sequence>s.sequence) latest_submission,
 coalesce(portal_private.internal_training_proofs(s.attendance_id,array(select evidence_id from public.crm_internal_training_submission_proof where submission_id=s.id)),false) intact_proof,
 v.value attendee,e.value times
 from public.crm_internal_training_submissions s
 join public.crm_training_attendee_accounts account on account.register_id=s.register_id and account.profile_id=p_user
 join public.profiles u on u.id=account.profile_id and u.role in ('admin','team')
 join lateral jsonb_array_elements(s.snapshot->'attendees') with ordinality v(value,ordinal) on v.value->>'kind'='Internal' and v.value->>'profile_id'=p_user::text
 join lateral jsonb_array_elements(s.snapshot->'attendance'->'entries') e(value) on (e.value->>'ordinal')::integer=v.ordinal-1
 join lateral(select * from public.crm_internal_training_decisions where submission_id=s.id and action='Approved' order by sequence desc limit 1) approved on true
 join lateral(select * from public.crm_internal_training_decisions where submission_id=s.id order by sequence desc limit 1) latest on true
 where s.snapshot->'source'->>'type'='Internal' and e.value->>'check_in' is not null and e.value->>'check_out' is not null
 )
 select id,tstzrange((times->>'check_in')::timestamptz,(times->>'check_out')::timestamptz,'[)'),
 latest_action='Approved' and source_current and latest_submission and intact_proof,
 jsonb_build_object('submission_id',id,'attendance_id',attendance_id,'register_id',register_id,'approval_id',approval_id,'approved_by',approved_by,'approved_at',approved_at,
 'latest_decision_id',latest_decision_id,'latest_action',latest_action,'user_id',p_user,'attendee_name',attendee->>'name',
 'source_kind',source_kind,'training_id',snapshot->'source'->'training_id','project_id',project_id,'definition_id',project_definition_id,
 'source_version',snapshot->'source'->'version','attendance_revision',snapshot->'attendance'->'revision','title',snapshot->'source'->'title',
 'check_in',times->>'check_in','check_out',times->>'check_out',
 'proof_ids',array(select evidence_id from public.crm_internal_training_submission_proof where submission_id=sources.id order by evidence_id),
 'eligibility',case when latest_action<>'Approved' then latest_action when not source_current then 'Superseded source or attendance' when not latest_submission then 'Superseded submission' when not intact_proof then 'Submitted proof unavailable' else 'Current approved' end)
 from sources;
$$;
create function portal_private.training_learning(p_user uuid,p_month date) returns jsonb
language sql stable security definer set search_path='' as $$
 with receipts as materialized(select * from portal_private.internal_learning_receipts(p_user)),
 activities as materialized(
 select a.id,a.actual_start,a.actual_end,c.hours,tstzrange(a.actual_start,a.actual_end,'[)') span
 from public.work_activities a join public.work_labour_costs c on c.activity_id=a.id
 where a.user_id=p_user and a.status='Approved' and a.activity_type='Training'
 ),
 credit as (
 select r.*,case when r.current_receipt then tstzmultirange(r.span)
 -coalesce((select range_agg(a.span) from activities a where a.span&&r.span),'{}'::tstzmultirange)
 -coalesce((select range_agg(prior.span) from receipts prior where prior.current_receipt and (lower(prior.span),prior.submission_id)<(lower(r.span),r.submission_id) and prior.span&&r.span),'{}'::tstzmultirange)
 else '{}'::tstzmultirange end credited_intervals
 from receipts r
 ),
 monthly as (
 select c.*,(select coalesce(sum(extract(epoch from upper(x)-lower(x))),0)/3600 from unnest(c.credited_intervals) x) credited_hours
 from credit c where (lower(c.span) at time zone 'Asia/Karachi')::date>=p_month and (lower(c.span) at time zone 'Asia/Karachi')::date<p_month+interval '1 month'
 ),
 totals as (
 select coalesce(sum(credited_hours),0) added,
 coalesce(jsonb_agg(receipt||jsonb_build_object('current',current_receipt,'elapsed_hours',extract(epoch from upper(span)-lower(span))/3600,'credited_hours',credited_hours,
 'credited_intervals',(select coalesce(jsonb_agg(jsonb_build_object('check_in',lower(x),'check_out',upper(x)) order by lower(x)),'[]') from unnest(credited_intervals) x)) order by lower(span),submission_id),'[]') sources from monthly
 ),
 legacy as (
 select coalesce(sum(hours),0) hours,coalesce(jsonb_agg(jsonb_build_object('activity_id',id,'check_in',actual_start,'check_out',actual_end,'hours',hours) order by actual_start,id),'[]') sources
 from activities where (actual_start at time zone 'Asia/Karachi')::date>=p_month and (actual_start at time zone 'Asia/Karachi')::date<p_month+interval '1 month'
 )
 select jsonb_build_object('user_id',p_user,'month',p_month,'approved_training_activity_hours',legacy.hours,'additional_internal_training_hours',totals.added,'learning_hours',legacy.hours+totals.added,
 'sources',totals.sources,'activity_sources',legacy.sources,
 'note','Actual elapsed intervals only. Internal receipts need the latest current lead/HR approval and intact submitted proof. External attendees, pending/returned/withdrawn and superseded receipts do not add credit. Overlaps with approved Training activities or other current Internal receipts count once. Existing activity start-month attribution in Asia/Karachi is retained; overlapping receipt time belongs to the earliest start, with submission ID as a stable tie-break. No breaks, rounding, thresholds, targets, weighted training score, paid activity or labour cost are created. Corrections change unlocked calculations; locked monthly snapshots remain unchanged.')
 from totals cross join legacy;
$$;
create function public.training_learning_credit(p_user uuid,p_month date) returns jsonb
language plpgsql stable security definer set search_path='' as $$
begin
 if p_month is null or not isfinite(p_month) or extract(day from p_month)<>1 then raise exception 'Choose first day of month';end if;
 if auth.uid() is null or not coalesce(portal_private.hr_read(p_user,p_month),false) or not exists(select 1 from public.profiles where id=p_user and role in ('admin','team')) then raise exception 'Own or current designated HR reporting scope for an internal staff account required';end if;
 return portal_private.training_learning(p_user,p_month);
end$$;
alter function portal_private.hr_month(uuid,date) rename to hr_month_before_internal_learning;
create function portal_private.hr_month(p_user uuid,p_month date) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare data jsonb;learning jsonb;
begin
 data:=portal_private.hr_month_before_internal_learning(p_user,p_month);
 learning:=portal_private.training_learning(p_user,p_month);
 return data||jsonb_build_object('learning_hours',learning->'learning_hours','training_learning',learning);
end$$;
revoke all on function portal_private.internal_learning_receipts(uuid),portal_private.training_learning(uuid,date),portal_private.hr_month_before_internal_learning(uuid,date),portal_private.hr_month(uuid,date) from public,anon,authenticated;
revoke all on function public.training_learning_credit(uuid,date) from public,anon;
grant execute on function public.training_learning_credit(uuid,date) to authenticated;
notify pgrst,'reload schema';
commit;
